--
-- Table structure for table `surveys`
--

DROP TABLE IF EXISTS `surveys`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `surveys` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned NOT NULL,
  `aadhaar_id` bigint(20) unsigned NOT NULL,
  `no_of_questions_answered` int(11) NOT NULL DEFAULT 0,
  `no_of_questions_unanswered` int(11) NOT NULL DEFAULT 0,
  `survey_json` longtext DEFAULT NULL,
  `json_path` varchar(255) DEFAULT NULL,
  `source` varchar(255) DEFAULT NULL,
  `verification_status` enum('pending','under_review','verified','rejected') DEFAULT 'pending',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `assigned_to` bigint(20) unsigned DEFAULT NULL,
  `verified_by` bigint(20) unsigned DEFAULT NULL,
  `verified_at` timestamp NULL DEFAULT NULL,
  `admin_corrections` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_aadhaar_id` (`aadhaar_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_aadhaar_id` (`aadhaar_id`),
  KEY `idx_assigned_to` (`assigned_to`),
  KEY `idx_verified_by` (`verified_by`),
  CONSTRAINT `fk_surveys_assigned_to` FOREIGN KEY (`assigned_to`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=47 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

